@Component("report-handler")
@ProcessingGroup("report-processing-group")
public class ReportEventHandler {
	
	// core constructor
	ReportEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateReportEvent
     */
    @EventHandler
    public void handle( CreateReportEvent event) {
        entityManager.persist(new Report(event.getReportId(), event.getReportName(), event.getGeneratedAt(), event.getFileUrl(), event.getAdAccount(), event.getCampaign(), event.getLineItem(), event.getReportType()));
    }

    /*
     * @param	event UpdateReportEvent
     */
    @EventHandler
    public Report handle( UpdateReportEvent event) {
    	entityManager.merge(new Report(event.getReportId(), event.getReportName(), event.getGeneratedAt(), event.getFileUrl(), event.getAdAccount(), event.getCampaign(), event.getLineItem(), event.getReportType()));
    }
    
    /*
     * @param	event DeleteReportEvent
     */
    @EventHandler
    public void on( DeleteReportEvent event) {
    	Report entity = new Report();
   
    	// ------------------------------------------
    	// apply the ReportId
    	// ------------------------------------------
    	entity.setReportId( event.getReportId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ReportRepository reportEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ReportEventHandler.class.getName());

}
